    def verify_bundle(self, bundle: EvidenceBundle) -> Tuple[bool, List[str]]:
        """Verify an evidence bundle's inclusion proofs against its Merkle root.

        Returns (all_valid, list_of_error_messages).
        """
        from bench.verification_chain import _compute_entry_hash, _compute_chain_hash
        errors: List[str] = []

        if len(bundle.records) != len(bundle.inclusion_proofs):
            return False, ["Mismatch between number of records and proofs"]

        for i, (record, proof) in enumerate(
            zip(bundle.records, bundle.inclusion_proofs)
        ):
            try:
                expected_entry = _compute_entry_hash(record.get("sealed_body", {}))
                expected_chain = _compute_chain_hash(record.get("prev_hash", ""), expected_entry)
                if record.get("chain_hash") != expected_chain or expected_chain != proof.get("chain_hash"):
                    errors.append(f"Record {i}: chain_hash mismatch or tampered record")
                    continue
            except Exception as e:
                errors.append(f"Record {i}: integrity check failed ({e})")
                continue

            valid = self._chain.verify_inclusion_proof(proof, bundle.merkle_root)
            if not valid:
                errors.append(
                    f"Record {i} (seq={record.get('sealed_body', {}).get('seq', '?')}): "
                    f"inclusion proof invalid"
                )
        return len(errors) == 0, errors
